mapper.select:
SELECT * FROM sys_message
WHERE tenant_id = #{tenantId}
AND type = #{query.type}
AND send_channel = #{query.channel}
AND status = #{query.status}
AND create_time >= #{startTime}
AND create_time <= #{endTime}

    AND (title LIKE CONCAT('%', #{query.keyword}, '%') OR content LIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY create_time DESC

SELECT m.*
FROM sys_message m
WHERE m.biz_type = #{bizType}
  AND m.biz_key = #{bizKey}
ORDER BY m.create_time DESC, m.id DESC
LIMIT 1

SELECT m.*
FROM sys_message m
WHERE m.tenant_id = #{tenantId}
  AND m.idempotency_key = #{idempotencyKey}
LIMIT 1
